import { ChangeDetectionStrategy, Component, ElementRef, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { of } from 'rxjs';
import { debounceTime, delay, distinctUntilChanged, map, startWith, switchMap, tap } from 'rxjs/operators';

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ReactiveFormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css'],
  host: {
    '(document:mousedown)': 'onDocMouseDown($event)'
  }
})
export class AppComponent {
  private readonly host = inject(ElementRef<HTMLElement>);

  readonly listboxId = 'autocomplete-listbox';

  private readonly cities: string[] = [
    'Amsterdam', 'Ankara', 'Athens', 'Austin',
    'Barcelona', 'Berlin', 'Boston', 'Brussels',
    'Chicago', 'Copenhagen',
    'Dubai',
    'Edinburgh',
    'Frankfurt',
    'Hamburg',
    'Istanbul', 'Izmir',
    'London', 'Los Angeles',
    'Madrid', 'Miami', 'Milan', 'Munich',
    'New York',
    'Oslo',
    'Paris', 'Prague',
    'Rome',
    'San Diego', 'San Francisco', 'San Jose', 'Seattle',
    'Tokyo',
    'Vienna',
    'Zurich'
  ];

  readonly queryControl = new FormControl('', { nonNullable: true });
  readonly query = toSignal(this.queryControl.valueChanges, { initialValue: this.queryControl.value });

  readonly isOpen = signal(false);
  readonly activeIndex = signal(-1);

  private pickedValue: string | null = null;

  // Typing (via [formControl]) and select() both set the control, so valueChanges carries every query.
  readonly results = toSignal(
    this.queryControl.valueChanges.pipe(
      startWith(this.queryControl.value),
      map((v: string) => v.trim()),
      debounceTime(300),
      distinctUntilChanged(),
      tap((q: string) => {
        // A pick fills the input, but it is not a new search.
        this.isOpen.set(!!q && q !== this.pickedValue);
        this.activeIndex.set(-1);
      }),
      switchMap((q: string) => (q ? this.search(q) : of([] as string[])))
    )
  );

  onInput(): void {
    this.pickedValue = null;
  }

  onFocus(): void {
    if (this.queryControl.value.trim()) this.isOpen.set(true);
  }

  onKeyDown(ev: KeyboardEvent): void {
    if (ev.key === 'Escape') {
      this.isOpen.set(false);
      this.activeIndex.set(-1);
      return;
    }

    // On a closed list the first arrow key only opens it: its options are not in the DOM until the next render.
    if (!this.isOpen() && (ev.key === 'ArrowDown' || ev.key === 'ArrowUp')) {
      this.isOpen.set(!!this.queryControl.value.trim());
    }

    const options = this.host.nativeElement.querySelectorAll('[role="option"]');
    const len = options.length;
    if (!this.isOpen() || len === 0) return;

    if (ev.key === 'ArrowDown') {
      ev.preventDefault();
      this.activeIndex.update((i) => (i < 0 ? 0 : (i + 1) % len));
      return;
    }

    if (ev.key === 'ArrowUp') {
      ev.preventDefault();
      this.activeIndex.update((i) => (i < 0 ? len - 1 : (i - 1 + len) % len));
      return;
    }

    if (ev.key === 'Enter') {
      const index = this.activeIndex();
      if (index >= 0 && index < len) {
        ev.preventDefault();
        const el = options[index] as HTMLElement;
        this.select(el.textContent ?? '');
      }
    }
  }

  select(value: string): void {
    this.pickedValue = value;
    this.queryControl.setValue(value);
    this.isOpen.set(false);
    this.activeIndex.set(-1);
  }

  optionId(i: number): string {
    return `opt-${i}`;
  }

  highlight(item: string, queryRaw: unknown): string {
    const q = String(queryRaw ?? '').trim();
    if (!q) return this.escapeHtml(item);

    const idx = item.toLowerCase().indexOf(q.toLowerCase());
    if (idx < 0) return this.escapeHtml(item);

    const before = this.escapeHtml(item.slice(0, idx));
    const mid = this.escapeHtml(item.slice(idx, idx + q.length));
    const after = this.escapeHtml(item.slice(idx + q.length));
    return `${before}<mark>${mid}</mark>${after}`;
  }

  onDocMouseDown(ev: MouseEvent): void {
    const target = ev.target as Node | null;
    if (!target) return;
    if (!this.host.nativeElement.contains(target)) {
      this.isOpen.set(false);
      this.activeIndex.set(-1);
    }
  }

  private search(q: string) {
    const needle = q.toLowerCase();
    const filtered = this.cities
      .filter((c) => c.toLowerCase().includes(needle))
      .slice(0, 8);

    return of(filtered).pipe(delay(150));
  }

  private escapeHtml(s: string): string {
    return s
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }
}

